code='''def transform(grid):
    h,w=len(grid),len(grid[0])
    bg=next((v for row in grid for v in row if v not in (2,)), 0)
    rs=[r for r in range(h) if all(x==2 for x in grid[r])]
    cs=[c for c in range(w) if all(grid[r][c]==2 for r in range(h))]
    rb=[-1]+rs+[h]; cb=[-1]+cs+[w]
    tiles=[]
    for ri in range(len(rb)-1):
        for ci in range(len(cb)-1):
            r0,r1=rb[ri]+1,rb[ri+1]; c0,c1=cb[ci]+1,cb[ci+1]
            tiles.append((r0,r1,c0,c1))
    # Motif is the set of non-background cells in the input, expressed by tile-relative coordinates.
    motif=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v not in (bg,2):
                for r0,r1,c0,c1 in tiles:
                    if r0<=r<r1 and c0<=c<c1:
                        motif.append((r-r0,c-c0,v)); break
    out=[row[:] for row in grid]
    for r0,r1,c0,c1 in tiles:
        for dr,dc,v in motif:
            if r0+dr<r1 and c0+dc<c1: out[r0+dr][c0+dc]=v
    return out
'''
open(p,'w').write(code)
